static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;
  DATA_TYPE path_new, path_old;
  #pragma scop
  #pragma omp parallel
  {
    #pragma omp master
    {
      for (k = 0; k < _PB_N; k++)
      { 
        #pragma omp for shared (k) private (j)
        for(i = 0; i < _PB_N; i++)
          for (j = 0; j < _PB_N; j++)
          {
            path_old = path[i][j];
            path_new = path[i][k] + path[k][j];
            #pragma omp critical
            path[i][j] = (path[i][j] < path_new)
              ? path[i][j]
              : path_new;
      }
    }
  }
  #pragma endscop
}

