kernel:
static
void kernel_conv2d(int ni,
		   int nj,
		   DATA_TYPE POLYBENCH_2D(A,NI,NJ,ni,nj),
		   DATA_TYPE POLYBENCH_2D(B,NI,NJ,ni,nj))
{
  int i, j;
  #pragma scop
  #pragma omp parallel for private(j) collapse(2) schedule(static)
  for (i = 1; i < _PB_NI - 1; ++i)
  {
    for (j = 1; j < _PB_NJ - 1; ++j)
    {
	    B[i][j] =  0.2 * A[i-1][j-1] + 0.5 * A[i-1][j] + -0.8 * A[i-1][j+1]
              + -0.3 * A[ i ][j-1] + 0.6 * A[ i ][j] + -0.9 * A[ i ][j+1]
              +  0.4 * A[i+1][j-1] + 0.7 * A[i+1][j] +  0.1 * A[i+1][j+1];
    }
  }
  #pragma endscop
}

serial:
static
void kernel_conv2d(int ni,
		   int nj,
		   DATA_TYPE POLYBENCH_2D(A,NI,NJ,ni,nj),
		   DATA_TYPE POLYBENCH_2D(B,NI,NJ,ni,nj))
{
  int i, j;
  for (i = 1; i < _PB_NI - 1; ++i)
  {
    for (j = 1; j < _PB_NJ - 1; ++j)
    {
	    B[i][j] =  0.2 * A[i-1][j-1] + 0.5 * A[i-1][j] + -0.8 * A[i-1][j+1]
              + -0.3 * A[ i ][j-1] + 0.6 * A[ i ][j] + -0.9 * A[ i ][j+1]
              +  0.4 * A[i+1][j-1] + 0.7 * A[i+1][j] +  0.1 * A[i+1][j+1];
    }
  }
}

kernel:
static
void kernel_conv2d(int ni,
		   int nj,
		   int nk,
		   DATA_TYPE POLYBENCH_3D(A,NI,NJ,NK,ni,nj,nk),
		   DATA_TYPE POLYBENCH_3D(B,NI,NJ,NK,ni,nj,nk))
{
  int i, j, k;
  #pragma scop
  #pragma omp parallel
  {
    #pragma omp for private (j,k) collapse(2)
    for (i = 1; i < _PB_NI - 1; ++i)
      for (j = 1; j < _PB_NJ - 1; ++j)
	for (k = 1; k < _PB_NK - 1; ++k)
	  {
             B[i][j][k]
	       =  2 * A[i-1][j-1][k-1]  +  4 * A[i+1][j-1][k-1]
	       +  5 * A[i-1][j-1][k-1]  +  7 * A[i+1][j-1][k-1]
	       + -8 * A[i-1][j-1][k-1]  + 10 * A[i+1][j-1][k-1]
	       + -3 * A[ i ][j-1][ k ]
	       +  6 * A[ i ][ j ][ k ]
	       + -9 * A[ i ][j+1][ k ]
	       +  2 * A[i-1][j-1][k+1]  +  4 * A[i+1][j-1][k+1]
	       +  5 * A[i-1][ j ][k+1]  +  7 * A[i+1][ j ][k+1]
	       + -8 * A[i-1][j+1][k+1]  + 10 * A[i+1][j+1][k+1];
           }
  }
  #pragma endscop
}

static
void kernel_jacobi_1d_imper(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i, j;

  #pragma scop
  #pragma omp parallel
  {
    #pragma omp master
    {
      for (t = 0; t < _PB_TSTEPS; t++)
      {
        #pragma omp for schedule(static)
        for (i = 1; i < _PB_N - 1; i++)
          B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);
        #pragma omp barrier

        #pragma omp for schedule(static)
        for (j = 1; j < _PB_N - 1; j++)
          A[j] = B[j];
        #pragma omp barrier
      }
    }
  }
  #pragma endscop
}

