		    DATA_TYPE POLYBENCH_1D(tmp,N,n),
		    DATA_TYPE POLYBENCH_1D(x,N,n),
		    DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  #pragma scop
  #pragma omp parallel
  {
    #pragma omp for private (j)
    for (i = 0; i < _PB_N; i++)
      {
        tmp[i] = 0;
	y[i] = 0;
	for (j = 0; j < _PB_N; j++)
	  {
            tmp[i] = A[i][j] * x[j] + tmp[i];
	    y[i] = B[i][j] * x[j] + y[i];
          }
	y[i] = alpha * tmp[i] + beta * y[i];
      }
  }
  #pragma endscop
}

