		 DATA_TYPE POLYBENCH_2D(B,NI,NJ,ni,nj))
{
  int i, j, k;
  DATA_TYPE acc;
  {
    /*  C := alpha*A*B + beta*C, A is symetric */
    for (i = 0; i < _PB_NI; i++)
      for (j = 0; j < _PB_NJ; j++)
	{
