static
void kernel_syrk(int ni, int nj,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NI,ni,ni),
		 DATA_TYPE POLYBENCH_2D(A,NI,NJ,ni,nj))
{
  int i, j, k;
  #pragma scop
  #pragma omp parallel
  {
    /*  C := alpha*A*A' + beta*C */
    #pragma omp for private(j)
    for (i = 0; i < _PB_NI; i++)
      for (j = 0; j < _PB_NI; j++)
	C[i][j] *= beta;
    #pragma omp for private(j,k)
    for (i = 0; i < _PB_NI; i++)
      for (j = 0; j < _PB_NI; j++)
	for (k = 0; k < _PB_NJ; k++)
	  C[i][j] += alpha * A[i][k] * A[j][k];
  }
  #pragma endscop
}

